test_suite:
test('ctx is null before a canvas is attached', () => {
  const { result } = renderHook(() => useCanvas());
  expect(result.current.ctx).toBeNull();
});

test('ctx is available once ref is attached to a canvas', () => {
  let hook: any;
  function Board() {
    hook = useCanvas();
    return <canvas ref={hook.ref} width={10} height={10} />;
  }
  render(<Board />);
  expect(hook.ctx).not.toBeNull();
});

test('clear is a function', () => {
  const { result } = renderHook(() => useCanvas());
  expect(typeof result.current.clear).toBe('function');
});

test('getImageData is a function', () => {
  const { result } = renderHook(() => useCanvas());
  expect(typeof result.current.getImageData).toBe('function');
});

test('clear does not throw when ctx is null', () => {
  const { result } = renderHook(() => useCanvas());
  expect(() => result.current.clear()).not.toThrow();
});

// __hidden__
test('getImageData returns null when ctx is null', () => {
  const { result } = renderHook(() => useCanvas());
  expect(result.current.getImageData()).toBeNull();
});

solution:
import { useRef, useState, useCallback, useEffect } from 'react';

export function useCanvas() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [ctx, setCtx] = useState<CanvasRenderingContext2D | null>(null);

  const ref = useCallback((el: HTMLCanvasElement | null) => {
    canvasRef.current = el;
    if (el) {
      setCtx(el.getContext('2d'));
    } else {
      setCtx(null);
    }
  }, []);

  const clear = useCallback(() => {
    const canvas = canvasRef.current;
    const context = ctx;
    if (!canvas || !context) return;
    context.fillStyle = 'white';
    context.fillRect(0, 0, canvas.width, canvas.height);
  }, [ctx]);

  const getImageData = useCallback((): ImageData | null => {
    const canvas = canvasRef.current;
    const context = ctx;
    if (!canvas || !context) return null;
    return context.getImageData(0, 0, canvas.width, canvas.height);
  }, [ctx]);

  return { ref, ctx, clear, getImageData };
}
